package com.ekayn.api.repo; import com.ekayn.api.model.Order; import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import jakarta.persistence.LockModeType;
public interface OrderRepository extends JpaRepository<Order,UUID> { List<Order> findByUserIdOrderByCreatedAtDesc(UUID userId); List<Order> findAllByOrderByCreatedAtDesc(); Optional<Order> findByIdAndUserId(UUID id,UUID userId); Optional<Order> findByStripeCheckoutSessionId(String sessionId); Optional<Order> findByStripeCheckoutSessionIdAndUserId(String sessionId,UUID userId); Optional<Order> findByUserIdAndCheckoutIdempotencyKey(UUID userId,String key); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select o from Order o where o.stripeCheckoutSessionId = :sessionId") Optional<Order> findByStripeCheckoutSessionIdForUpdate(@Param("sessionId") String sessionId); }
